<?php namespace App\Notifications; use Illuminate\Bus\Queueable; 
use Illuminate\Notifications\Notification; 
class NewLaundryRequestNotification 
extends Notification { use Queueable; public $laundry; public function __construct($laundry) { $this->laundry = $laundry; } public function via($notifiable) { return ['database']; } public function toArray($notifiable) { return [ 'type' => 'laundry', 'title' => 'Request Laundry Baru', 'message' => $this->laundry->reservasi->tamu->nama . ' (' . ($this->laundry->reservasi->kamar->nomor_kamar ?? 'N/A') . ') mengajukan laundry.', 'url' => route('admin.laundry') ]; } }